class ConfigFileSettingsSource(PydanticBaseSettingsSource):
    """
    A simple settings source that loads variables from a yaml file in GTO DIR.

    The config file location is taken from ``CONFIG_FILE_NAME`` as resolved by
    the sources that precede this one (init kwargs, then environment).
    """

    def get_field_value(  # pylint: disable=arguments-renamed
        self, field: FieldInfo, field_name: str
    ):
        # all values are produced at once in __call__
        return None, field_name, False

    def __call__(self) -> Dict[str, Any]:
        encoding = self.settings_cls.model_config.get("env_file_encoding")
        config_file = self.current_state.get("CONFIG_FILE_NAME", CONFIG_FILE_NAME)
        if not isinstance(config_file, Path):
            config_file = Path(config_file)
